1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Step =
11	  | { op: "quote"; items: Item[] }
12	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
13	
14	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
15	
16	export type QuoteResult = { premium: number };
17	export type ClaimResult = { payout: number; remainingCap: number };
18	export type Result = QuoteResult | ClaimResult;
19	
20	const PROCESSING_FEE = 5;
21	// Every damage event carries a deductible, borne by the customer.
22	const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;
23	const BASE_PREMIUMS: Record<string, number> = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	  rune: 25,
29	  moonstone: 25,
30	};
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	const LOYALTY_YEARS_THRESHOLD = 2;
33	const LOYALTY_DISCOUNT_RATE = 0.2;
34	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
35	const CURSE_SURCHARGE_RATE = 0.5;
36	const HIGH_ENCHANTMENT_THRESHOLD = 5;
37	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
38	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
39	// A building block of alike components is priced as a unit, not per piece.
40	const COMPONENT_BLOCK_SIZE = 3;
41	const COMPONENT_BLOCK_PREMIUM = 60;
42	// Unmodified insurance value per item; the sum over a policy bounds what can be paid out.
43	const INSURANCE_VALUES: Record<string, number> = {
44	  sword: 1000,
45	  amulet: 600,
46	  rune: 250,
47	};
48	// A policy pays out at most twice its insurance sum.
49	const PAYOUT_CAP_MULTIPLIER = 2;
50	// Damage to strongly enchanted items is only partially reimbursed (a stricter bar than the premium surcharge).
51	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
52	const PARTIAL_REIMBURSEMENT_RATE = 0.5;
53	
54	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
55	
56	const formsBlock = (type: string, count: number): boolean =>
57	  isComponent(type) && count === COMPONENT_BLOCK_SIZE;
58	
59	const premiumForTypeGroup = (type: string, count: number): number =>
60	  formsBlock(type, count) ? COMPONENT_BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
61	
62	const countOfType = (items: Item[], type: string): number =>
63	  items.filter((item) => item.type === type).length;
64	
65	const calculateBasePremium = (items: Item[]): number => {
66	  const types = [...new Set(items.map((item) => item.type))];
67	  return types.reduce(
68	    (total, type) => total + premiumForTypeGroup(type, countOfType(items, type)),
69	    0,
70	  );
71	};
72	
73	// Item-specific modifiers: each applies a rate to the base premium of every affected item.
74	const itemSurcharge = (items: Item[], applies: (item: Item) => boolean, rate: number): number =>
75	  items
76	    .filter(applies)
77	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
78	
79	const isCursed = (item: Item): boolean => item.cursed === true;
80	
81	const isHighlyEnchanted = (item: Item): boolean =>
82	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
83	
84	const curseSurcharge = (items: Item[]): number =>
85	  itemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
86	
87	const enchantmentSurcharge = (items: Item[]): number =>
88	  itemSurcharge(items, isHighlyEnchanted, ENCHANTMENT_SURCHARGE_RATE);
89	
90	// Policy-wide modifiers: each applies to the policy base premium (sum of item base premiums).
91	const firstInsuranceSurcharge = (basePremium: number): number =>
92	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
93	
94	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
95	  yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
96	
97	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
98	  isLoyalCustomer(yearsWithMHPCO) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
99	
100	const followUpDiscount = (basePremium: number, isFollowUpContract: boolean): number =>
101	  isFollowUpContract ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
102	
103	// Premiums are rounded up to whole G, in the MHPCO's favour.
104	const roundUpToWholeGold = (amount: number): number => Math.ceil(amount);
105	
106	// Payouts are rounded down to whole G, in the MHPCO's favour.
107	const roundDownToWholeGold = (amount: number): number => Math.floor(amount);
108	
109	// What the MHPCO knows about the customer at the moment a quote is issued.
110	type CustomerContext = { yearsWithMHPCO: number; isFollowUpContract: boolean };
111	
112	// The MHPCO only insures item types it has a base premium for.
113	const isKnownItemType = (type: string): boolean => type in BASE_PREMIUMS;
114	
115	const assertKnownItemType = (type: string): void => {
116	  if (!isKnownItemType(type)) throw new Error(`Unknown item type: ${type}`);
117	};
118	
119	const assertKnownItemTypes = (items: Item[]): void =>
120	  items.forEach((item) => assertKnownItemType(item.type));
121	
122	const quotePremium = (items: Item[], customer: CustomerContext): number => {
123	  assertKnownItemTypes(items);
124	  const basePremium = calculateBasePremium(items);
125	  const premiumBeforeFee =
126	    basePremium +
127	    curseSurcharge(items) +
128	    enchantmentSurcharge(items) +
129	    firstInsuranceSurcharge(basePremium) -
130	    loyaltyDiscount(basePremium, customer.yearsWithMHPCO) -
131	    followUpDiscount(basePremium, customer.isFollowUpContract);
132	  return roundUpToWholeGold(premiumBeforeFee + PROCESSING_FEE);
133	};
134	
135	const isPartiallyReimbursed = (item: Item | undefined): boolean =>
136	  (item?.enchantment ?? 0) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
137	
138	const reimbursedAmount = (item: Item | undefined, damage: Damage): number =>
139	  isPartiallyReimbursed(item) ? damage.amount * PARTIAL_REIMBURSEMENT_RATE : damage.amount;
140	
141	const findDamagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
142	  insuredItems.find((candidate) => candidate.type === damage.itemType);
143	
144	const payoutForDamage = (insuredItems: Item[], damage: Damage): number => {
145	  const item = findDamagedItem(insuredItems, damage);
146	  if (item === undefined) throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
147	  return reimbursedAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE_EVENT;
148	};
149	
150	const claimPayout = (insuredItems: Item[], damages: Damage[]): number =>
151	  damages.reduce((total, damage) => total + payoutForDamage(insuredItems, damage), 0);
152	
153	const insuranceSum = (items: Item[]): number =>
154	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
155	
156	const payoutCap = (items: Item[]): number => insuranceSum(items) * PAYOUT_CAP_MULTIPLIER;
157	
158	// A policy: the items it covers and how much it may still pay out.
159	type Policy = { items: Item[]; remainingCap: number };
160	
161	const openPolicy = (items: Item[]): Policy => ({ items, remainingCap: payoutCap(items) });
162	
163	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
164	  const payout = roundDownToWholeGold(
165	    Math.min(claimPayout(policy.items, damages), policy.remainingCap),
166	  );
167	  return { payout, remainingCap: policy.remainingCap - payout };
168	};
169	
170	// Every contract after the customer's first in a scenario is a follow-up contract.
171	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
172	
173	const customerContextAt = (scenario: Scenario, stepIndex: number): CustomerContext => ({
174	  yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
175	  isFollowUpContract: isFollowUpContract(stepIndex),
176	});
177	
178	export const runScenario = (scenario: Scenario): { results: Result[] } => {
179	  // Policies are referenced by the index of the quote step that created them.
180	  const policies = new Map<number, Policy>();
181	  const results = scenario.steps.map((step, index): Result => {
182	    if (step.op === "claim") {
183	      const policy = policies.get(step.policy) ?? openPolicy([]);
184	      const result = settleClaim(policy, step.incident.damages);
185	      policies.set(step.policy, { ...policy, remainingCap: result.remainingCap });
186	      return result;
187	    }
188	    policies.set(index, openPolicy(step.items));
189	    return { premium: quotePremium(step.items, customerContextAt(scenario, index)) };
190	  });
191	  return { results };
192	};
